import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"Forge Tool API Integration Contract","description":"","frontmatter":{},"headers":[],"relativePath":"forge/README.md","filePath":"forge/README.md"}'),i={name:"forge/README.md"};function s(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="forge-tool-api-integration-contract" tabindex="-1">Forge Tool API Integration Contract <a class="header-anchor" href="#forge-tool-api-integration-contract" aria-label="Permalink to &quot;Forge Tool API Integration Contract&quot;">​</a></h1><p><a href="/docs/forge/README_zh">中文</a> · <a href="/docs/en/">Documentation index</a></p><blockquote><p>Applies to PhyAgentOS 1.0.0.</p></blockquote><h2 id="_1-execution-boundary" tabindex="-1">1. Execution boundary <a class="header-anchor" href="#_1-execution-boundary" aria-label="Permalink to &quot;1. Execution boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AgentTask-bound call / diagnostic Query</span></span>
<span class="line"><span>        → ForgeToolClient</span></span>
<span class="line"><span>        → Gateway /tools → ToolInvocation → ToolEndpoint</span></span>
<span class="line"><span>        → Dora and robot nodes</span></span></code></pre></div><p>PAOS supports Query, Action, and Session semantics. AgentTask aggregates a user goal, but Gateway remains the physical execution owner. Diagnostic Query may run without a task; Action and task-owned Session calls require a frozen AgentTask binding. The selected Endpoint operation enforces <code>max_concurrency</code>; PAOS does not introduce a cross-Tool Resource/Control lease.</p><h2 id="_2-tool-discovery-and-context" tabindex="-1">2. Tool discovery and context <a class="header-anchor" href="#_2-tool-discovery-and-context" aria-label="Permalink to &quot;2. Tool discovery and context&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /tools</span></span>
<span class="line"><span>GET /tools/{tool_id}</span></span>
<span class="line"><span>GET /tools/{tool_id}/context</span></span></code></pre></div><p>A ToolSpec declares stable identity, implementation/Endpoint binding, operation, <code>query|action|session</code> semantics, strict input/output schema, readiness, and robot frame profile. Context is read live before invocation; callers do not infer frame, unit, readiness, or binding.</p><h2 id="_3-query-contract" tabindex="-1">3. Query contract <a class="header-anchor" href="#_3-query-contract" aria-label="Permalink to &quot;3. Query contract&quot;">​</a></h2><p><code>forge_tool_query</code> reads the configured ToolSpec, verifies <code>semantics=query</code>, then invokes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /tools/{endpoint_id}/{operation}:invoke</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;arguments&quot;: {},</span></span>
<span class="line"><span>  &quot;caller_id&quot;: &quot;paos:&lt;task-or-diagnostic-identity&gt;&quot;,</span></span>
<span class="line"><span>  &quot;timeout_ms&quot;: 10000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Success is HTTP 200 with <code>{ &quot;ok&quot;: true, &quot;data&quot;: { ... } }</code>. PAOS generates the caller ID. A bound Query creates a terminal PAOS ToolExecutionRecord under the active PlanRevision. An unbound Query returns the same Gateway data without task attribution.</p><h2 id="_4-action-contract" tabindex="-1">4. Action contract <a class="header-anchor" href="#_4-action-contract" aria-label="Permalink to &quot;4. Action contract&quot;">​</a></h2><p>Admission:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /tools/{tool_id}:invoke</span></span>
<span class="line"><span>→ HTTP 202</span></span>
<span class="line"><span>→ data.invocation_id + data.attempt_id</span></span></code></pre></div><p>Reconciliation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /invocations/{invocation_id}</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}/result</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/cancel</span></span></code></pre></div><p>Result HTTP 202 means pending. Cancel HTTP 200/202 means the cancellation request was processed or accepted; it does not prove stop. A timeout means the remote state is unknown. An explicit <code>unknown</code> terminal outcome closes PAOS accounting as a failure but remains physically uncertain and must not trigger a blind retry.</p><p>Before admission PAOS persists an Action intent and its generated caller ID. Every returned invocation/attempt identity is retained. A timeout or transport error leaves an <code>unknown</code> record; recovery may only read a persisted invocation ID and never repeats the POST blindly.</p><h2 id="_5-session-contract" tabindex="-1">5. Session contract <a class="header-anchor" href="#_5-session-contract" aria-label="Permalink to &quot;5. Session contract&quot;">​</a></h2><p>A Tool with <code>semantics=session</code> is admitted through the same invoke route and returns HTTP 202 plus an invocation ID. Status and result use the common <code>/invocations/{id}</code> routes; an owned Session is stopped with <code>POST /invocations/{id}/stop</code>.</p><p>PAOS records Session ownership as <code>task</code>, <code>shared</code>, or <code>runtime</code>. A task can stop only its own Session, shared Sessions remain live across task finalization, and runtime-owned Sessions are managed outside the Agent. Non-terminal task-owned Sessions block finalization and Runtime stop also accounts for all active Sessions.</p><h2 id="_6-agent-tools" tabindex="-1">6. Agent tools <a class="header-anchor" href="#_6-agent-tools" aria-label="Permalink to &quot;6. Agent tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tool</th><th style="text-align:left;">Contract</th></tr></thead><tbody><tr><td style="text-align:left;"><code>forge_tool_context</code></td><td style="text-align:left;">Read ToolSpec and live context.</td></tr><tr><td style="text-align:left;"><code>forge_tool_query</code></td><td style="text-align:left;">Invoke synchronous Query; diagnostic without a task or governed with <code>task_id</code>.</td></tr><tr><td style="text-align:left;"><code>forge_tool_start_action</code></td><td style="text-align:left;">Admit an asynchronous Action for a bound <code>task_id</code>.</td></tr><tr><td style="text-align:left;"><code>forge_tool_action_status</code></td><td style="text-align:left;">Read invocation phase/status.</td></tr><tr><td style="text-align:left;"><code>forge_tool_action_result</code></td><td style="text-align:left;">Read pending or terminal result.</td></tr><tr><td style="text-align:left;"><code>forge_tool_cancel_action</code></td><td style="text-align:left;">Request cancellation without asserting stop.</td></tr><tr><td style="text-align:left;"><code>forge_tool_start_session</code></td><td style="text-align:left;">Admit a bound Session with explicit ownership.</td></tr><tr><td style="text-align:left;"><code>forge_tool_session_status/result/stop_session</code></td><td style="text-align:left;">Reconcile or stop an owned Session.</td></tr><tr><td style="text-align:left;"><code>forge_task_create</code></td><td style="text-align:left;">Create the one active AgentTask and revision 1.</td></tr><tr><td style="text-align:left;"><code>forge_task_get</code></td><td style="text-align:left;">Read task, revisions, Tool records, evidence, and verdict.</td></tr><tr><td style="text-align:left;"><code>forge_task_begin_revision</code></td><td style="text-align:left;">Append a revision after an allowed recovery verdict.</td></tr><tr><td style="text-align:left;"><code>forge_task_finalize</code></td><td style="text-align:left;">Capture after evidence and apply aggregate task verification.</td></tr><tr><td style="text-align:left;"><code>forge_task_cancel</code></td><td style="text-align:left;">Cancel non-terminal Actions and stop task-owned Sessions.</td></tr></tbody></table><p>The diagnostic context tool remains available without a Runtime. Governed tools require exactly one healthy active Skill Runtime. Existing general Agent tools and dynamic MCP tools remain registered independently.</p><h2 id="_7-binding-identity-and-correlation" tabindex="-1">7. Binding, identity, and correlation <a class="header-anchor" href="#_7-binding-identity-and-correlation" aria-label="Permalink to &quot;7. Binding, identity, and correlation&quot;">​</a></h2><p><code>activate_skill</code> reads the installed workflow and previews the current Runtime. Task creation revalidates that candidate and freezes the Skill name/version, manifest and workflow hashes, profile, Runtime instance, Gateway identity, required ToolSpec hashes and Node artifact IDs. Every task execution rechecks membership, semantics, readiness, ToolSpec hash, and Runtime identity.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">Owner</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Stable task aggregate</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Immutable planning generation</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Immutable Skill/Runtime/ToolSpec snapshot</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Bound Query, Action, or Session record</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Idempotency/correlation identity persisted before admission</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">Asynchronous Action or Session lifecycle</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">Execution attempt</td></tr></tbody></table><p>Correlation is explicit. IDs are not aliases and are not derived from one another.</p><h2 id="_8-agenttask-model" tabindex="-1">8. AgentTask model <a class="header-anchor" href="#_8-agenttask-model" aria-label="Permalink to &quot;8. AgentTask model&quot;">​</a></h2><p>Only one AgentTask may be non-terminal globally; diagnostic Query does not occupy the slot. Creation and updates use SQLite WAL and immediate transactions. A task contains an append-only list of PlanRevisions. Each revision contains Tool records, a semantic verdict, and verification attempts.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>executing</span></span>
<span class="line"><span>  ├─ finalize → succeeded | failed</span></span>
<span class="line"><span>  ├─ recovery verdict → awaiting_replan → begin_revision → executing</span></span>
<span class="line"><span>  └─ cancel → cancelling → reconcile → finalize → cancelled | failed</span></span></code></pre></div><p>Once a Tool record is terminal, later observations do not rewrite its execution fact. A recovery revision keeps the same task ID and is bounded by replan count and deadline.</p><h2 id="_9-evidence-and-verification" tabindex="-1">9. Evidence and verification <a class="header-anchor" href="#_9-evidence-and-verification" aria-label="Permalink to &quot;9. Evidence and verification&quot;">​</a></h2><p>PAOS performs best-effort capture before the first bound Action and after every bound Action reaches terminal accounting state. Evidence artifacts include source, phase, sequence, timestamps, media metadata, size, SHA-256, and workspace-relative references. Capture errors are recorded rather than hidden. Bundle identity, quality, capture-window, policy requirements, and retained artifact bytes are validated before the verifier receives the task context.</p><p><code>forge_task_finalize</code> aggregates all bound Tool facts and applies the task contract:</p><ul><li><code>off</code>: execution-derived result;</li><li><code>audit</code>: record semantic verdict, preserve execution-derived result;</li><li><code>enforce</code>: semantic verdict controls success and fails closed;</li><li><code>recovery</code>: enforce semantics plus bounded <code>replan_required</code>.</li></ul><p>Forge ToolResult and events are authoritative for execution. The PAOS verifier decides only whether the user-level task is complete. Its context includes the frozen Skill binding, PlanRevisions, ToolExecutionRecords, Gateway terminal results, before/after evidence, and scoped advisory Lessons.</p><h2 id="_10-experience-and-evolution" tabindex="-1">10. Experience and evolution <a class="header-anchor" href="#_10-experience-and-evolution" aria-label="Permalink to &quot;10. Experience and evolution&quot;">​</a></h2><p>The terminal AgentTask is adapted into one redacted episode. It references the frozen Skill binding and version, PlanRevision verdicts, ToolInvocation/attempt fingerprints, and evidence without persisting raw outputs, credentials, endpoints, or physical parameters in learned content.</p><p>Lessons and failure clusters are scoped to the bound Skill version. Evolution is fail-open and never alters Gateway facts, AgentTask terminal state, or verification attempts.</p><h2 id="_11-skill-runtime-and-distribution" tabindex="-1">11. Skill Runtime and distribution <a class="header-anchor" href="#_11-skill-runtime-and-distribution" aria-label="Permalink to &quot;11. Skill Runtime and distribution&quot;">​</a></h2><p>Skill Runtime installs and manages manifest-v2 Bundles. Installation requires safe contained paths, bounded extraction, SHA-256 file inventory, strict manifest validation, staging, atomic replacement, and rollback. Each Node lock fixes artifact ID, version, platform, architecture, archive type, root executable name, and SHA-256. Static-index downloads carry size and digest. Registry Node downloads use the verified Skill lock as the digest authority and resolve an exact size from Registry metadata or the direct-download endpoint before entering the cache. Installation is explicit and confirmed by default.</p><p>RuntimeManager requires Dora CLI on <code>PATH</code> (v0.4.1 with <code>dora-message</code> v0.7.0 is the current Forge Skill compatibility baseline). It materializes an environment whose digest covers the selected dataflow path and profile file contents. <code>PAOS_SKILL_NAME</code> and <code>PAOS_SKILL_VERSION</code> are available both to Dora processes and as rendered dataflow placeholders.</p><p>Startup persists <code>starting</code>, then runs <code>bash &lt;bundle&gt;/start.sh &lt;name&gt; &lt;version&gt;</code> with inherited stdio when the optional hook exists. Hook-enabled Bundles require Bash. After the hook succeeds, RuntimeManager starts local Dora services when needed, launches the named profile, waits for Gateway <code>/tools</code> and all required Tool contexts, and persists status/logs. A healthy active Runtime contributes Skill availability; its manifest is the only source of the Gateway URL. Per-Skill cross-process locking rejects overlapping lifecycle mutations.</p><p>Normal stop is rejected while tracked non-terminal invocations, Sessions, or task bindings exist. Force stop records an audit event and does not change execution truth.</p><p>Concrete Forge Skills, nodes, models, and simulation assets are not part of the PhyAgentOS source or Python distribution. They are obtained independently for local testing or deployment. The packaging helper creates deterministic Skill archives and the installer verifies them before commit.</p><h2 id="_12-conformance" tabindex="-1">12. Conformance <a class="header-anchor" href="#_12-conformance" aria-label="Permalink to &quot;12. Conformance&quot;">​</a></h2><p>An integration is conformant when it covers Tool discovery/context, Query response, Action and Session admission, pending and terminal result, cancellation/stop, timeout/unknown, no-POST recovery, endpoint concurrency, immutable AgentTask binding/revisions, ownership, evidence, aggregate verification, version-scoped experience, Bundle security, transactional installation, Runtime health, safe switch, and availability propagation.</p><p>Mock Gateway tests are sufficient for code and contract acceptance. Hardware/MuJoCo acceptance is recorded separately with exact artifact digests and environment.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/docs/en/01-framework-introduction">Framework Introduction</a></li><li><a href="/docs/en/04-forge-configuration-reference">Configuration Reference</a></li><li><a href="/docs/user_development_guide/README_en">Integration Development Guide</a></li><li><a href="/docs/user_manual/README_en">Operations Manual</a></li></ul>`,53)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
